}

function highlightAnswers() {
  questions.forEach((q) => {
    const sel = getSelections(q.id);
    q.choices.forEach((choice) => {
      const label = document.querySelector(`label[for="${q.id}-${choice.value}"]`);
      const isSelected = sel.includes(choice.value);
      const isCorrect = q.correct.includes(choice.value);

      label.classList.remove("selected");
      if (isSelected && isCorrect) label.classList.add("answer-correct");
      else if (isSelected && !isCorrect) label.classList.add("answer-incorrect");
      else if (!isSelected && isCorrect) label.classList.add("answer-correct");
    });
  });
}

document.getElementById("quiz-form").addEventListener("submit", (e) => {
  e.preventDefault();
  let score = 0;
  questions.forEach((q) => {
    if (arraysEqual(getSelections(q.id), q.correct)) score++;
  });
  highlightAnswers();
  lockForm();
  showResults(score);
  document.getElementById("results").scrollIntoView({ behavior: "smooth", block: "nearest" });
});

document.getElementById("retry-btn").addEventListener("click", () => {
  document.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
    cb.checked = false;
    cb.disabled = false;
  });
  document.querySelectorAll(".choice").forEach((c) => {
    c.classList.remove("selected", "answer-correct", "answer-incorrect");
  });
  const submitBtn = document.querySelector(".submit-btn");
  submitBtn.disabled = false;
  submitBtn.style.opacity = "";
  submitBtn.style.cursor = "";
  document.getElementById("results").classList.remove("visible");
  document.querySelector(".progress-bar__fill").style.width = "0%";
  window.scrollTo({ top: 0, behavior: "smooth" });
});

buildQuiz();

