+const questions = [
+  {
+    id: "q1",
+    text: "Which of the following are statically typed languages?",
+    help: "Static typing means variable types are checked at compile time rather than at runtime. Select all that apply.",
+    choices: [
+      { value: "java", label: "Java" },
+      { value: "python", label: "Python" },
+      { value: "typescript", label: "TypeScript" },
+      { value: "rust", label: "Rust" },
+    ],
+    correct: ["java", "typescript", "rust"],
+  },
+  {
+    id: "q2",
+    text: "Which languages primarily use garbage collection for memory management?",
+    choices: [
+      { value: "go", label: "Go" },
+      { value: "c", label: "C" },
+      { value: "csharp", label: "C#" },
+      { value: "cpp", label: "C++" },
+    ],
+    correct: ["go", "csharp"],
+  },
+  {
+    id: "q3",
+    text: "Which of the following languages support first-class functions?",
+    choices: [
+      { value: "javascript", label: "JavaScript" },
+      { value: "haskell", label: "Haskell" },
+      { value: "cobol", label: "COBOL" },
+      { value: "python", label: "Python" },
+    ],
+    correct: ["javascript", "haskell", "python"],
+  },
+];
+
+function getSelections(qId) {
+  return Array.from(
+    document.querySelectorAll(`[name="${qId}"]:checked`)
+  ).map((cb) => cb.value);
+}
+
+function arraysEqual(a, b) {
+  return a.length === b.length && [...a].sort().every((v, i) => v === [...b].sort()[i]);
+}
+
+function updateProgress() {
+  const answered = questions.filter((q) => getSelections(q.id).length > 0).length;
+  const pct = (answered / questions.length) * 100;
+  document.querySelector(".progress-bar__fill").style.width = pct + "%";
+}
+
+function buildQuiz() {
+  const form = document.getElementById("quiz-form");
+
+  questions.forEach((q, idx) => {
+    const field = document.createElement("div");
+    field.className = "form-field";
+    field.setAttribute("role", "group");
+    field.setAttribute("aria-labelledby", `${q.id}-label`);
+
+    const labelEl = document.createElement("p");
+    labelEl.className = "form-field__label";
+    labelEl.id = `${q.id}-label`;
+    labelEl.innerHTML = `<span class="q-number" aria-hidden="true">${idx + 1}</span>${q.text}`;
+    field.appendChild(labelEl);
+
+    if (q.help) {
+      const help = document.createElement("p");
+      help.className = "form-field__help";
+      help.id = `${q.id}-help`;
+      help.textContent = q.help;
+      field.appendChild(help);
+      field.setAttribute("aria-describedby", `${q.id}-help`);
+    }
+
+    const choices = document.createElement("div");
+    choices.className = "choices";
+
+    q.choices.forEach((choice) => {
+      const label = document.createElement("label");
+      label.className = "choice";
+      label.htmlFor = `${q.id}-${choice.value}`;
+
+      const cb = document.createElement("input");
+      cb.type = "checkbox";
+      cb.name = q.id;
+      cb.id = `${q.id}-${choice.value}`;
+      cb.value = choice.value;
+
+      const span = document.createElement("span");
+      span.className = "choice__text";
+      span.textContent = choice.label;
+
+      cb.addEventListener("change", () => {
+        label.classList.toggle("selected", cb.checked);
+        updateProgress();
+      });
+
+      label.appendChild(cb);
+      label.appendChild(span);
+      choices.appendChild(label);
+    });
+
+    field.appendChild(choices);
+    form.insertBefore(field, form.querySelector(".submit-btn"));
+  });
+}
+
+function lockForm() {
+  document.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
+    cb.disabled = true;
+  });
+  document.querySelector(".submit-btn").disabled = true;
+  document.querySelector(".submit-btn").style.opacity = "0.5";
+  document.querySelector(".submit-btn").style.cursor = "default";
+}
+
+function showResults(score) {
+  const results = document.getElementById("results");
+  results.classList.add("visible");
+
+  document.getElementById("score-value").textContent = score;
+
+  const msgs = ["Keep practising! 💪", "Good effort! 👍", "Well done! 🎉"];
+  document.getElementById("results-message").textContent =
+    score === 0 ? msgs[0] : score === questions.length ? msgs[2] : msgs[1];
+
+  const breakdown = document.getElementById("breakdown");
+  breakdown.innerHTML = "";
+  questions.forEach((q, idx) => {
+    const sel = getSelections(q.id);
+    const correct = arraysEqual(sel, q.correct);
+    const item = document.createElement("div");
+    item.className = `breakdown-item ${correct ? "correct" : "incorrect"}`;
+    item.innerHTML = `<span class="icon" aria-hidden="true">${correct ? "✓" : "✗"}</span> Question ${idx + 1}: ${correct ? "Correct" : "Incorrect"}`;
+    breakdown.appendChild(item);
+  });
+}
+
+function highlightAnswers() {
+  questions.forEach((q) => {
+    const sel = getSelections(q.id);
+    q.choices.forEach((choice) => {
+      const label = document.querySelector(`label[for="${q.id}-${choice.value}"]`);
+      const isSelected = sel.includes(choice.value);
+      const isCorrect = q.correct.includes(choice.value);
+
+      label.classList.remove("selected");
+      if (isSelected && isCorrect) label.classList.add("answer-correct");
+      else if (isSelected && !isCorrect) label.classList.add("answer-incorrect");
+      else if (!isSelected && isCorrect) label.classList.add("answer-correct");
+    });
+  });
